('ex_core_pallof_band','band-pallof-press','Band Pallof Press','strength','["core", "obliques"]','["shoulders"]','["strength", "core", "anti_rotation", "resistance_bands", "no_floor", "low_impact", "quiet"]','["resistance_bands"]','{"steps": ["Anchor a band at chest height. Stand side-on, both hands on the band at your sternum.", "Step out until the band is taut.", "Press your hands straight out in front of you and hold \u2014 the band will try to rotate you.", "Return to the chest. Complete the reps, then change sides."], "cues": ["Do not let your torso twist \u2014 that is the whole exercise", "Squeeze the glutes to stop the hips rotating", "\ud83d\udca1 Anti-rotation was missing entirely; this is the core''s most transferable pattern"]}','{"supports": ["reps", "sets", "time"]}',1,'global',1789400000000,1789400000000),
